package uz.buxoro.murojaat;
import android.Manifest;import android.app.Activity;import android.os.Bundle;import android.webkit.PermissionRequest;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import android.content.pm.PackageManager;
public class MainActivity extends Activity{WebView w;@Override public void onCreate(Bundle b){super.onCreate(b);if(android.os.Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},7);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(true);s.setAllowUniversalAccessFromFileURLs(true);w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){runOnUiThread(()->r.grant(r.getResources()));}});w.loadUrl("file:///android_asset/index.html");}@Override public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}}